package dev.hatek.quickembedded;


final class QuickBoldMetricsPart0000 {
    private QuickBoldMetricsPart0000() {}
    static void put(byte[] output, int offset) {
        int cursor = offset;
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        cursor = QuickBoldMetrics.copy(output, cursor, "");
        if (cursor != offset + 32767) throw new IllegalStateException("Corrupt embedded data part");
    }
}
